55	function formatErrorDetail(detail: unknown, fallback: string): string {
56	  if (typeof detail === 'string') return detail;
57	  if (Array.isArray(detail)) {
58	    return detail
59	      .map((e: Record<string, unknown>) => e.msg || e.message || JSON.stringify(e))
60	      .join('; ');
61	  }
62	  if (detail && typeof detail === 'object') {
63	    const obj = detail as Record<string, unknown>;
64	    if (typeof obj.message === 'string') return obj.message;
65	    return JSON.stringify(detail);
66	  }
67	  return fallback;
68	}
